__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"SAMPLES",{enumerable:!0,get:function(){return o}});const o={support:{score:78,headline:'\ub9c8\ub978 \ub545\uc5d0 \ub2e8\ube44\uac00 \ub0b4\ub9ac\ub4ef \ub3c4\uc6c0\uc774 \uc2a4\uba70\ub4dc\ub294 \ud558\ub8e8\uc785\ub2c8\ub2e4.',overall:'\uc624\ub298\uc740 \ub0b4\uac00 \uc560\uc4f0\uc9c0 \uc54a\uc544\ub3c4 \uc8fc\ubcc0\uc5d0\uc11c \uc190\uc744 \ub0b4\ubbf8\ub294 \ub0a0\uc785\ub2c8\ub2e4. \uc624\ub798 \ubb35\ud600\ub454 \ubd80\ud0c1\uc744 \uaebc\ub0b4\uae30\uc5d0 \uc88b\uace0, \uc717\uc0ac\ub78c\uc774\ub098 \uc120\ubc30\uc758 \ud55c\ub9c8\ub514\uac00 \uc0dd\uac01\ubcf4\ub2e4 \ud070 \uae38\uc744 \uc5f4\uc5b4\uc90d\ub2c8\ub2e4. \ub2e4\ub9cc \ubc1b\ub294 \ubcf5\uc774 \ub9ce\uc740 \ub0a0\uc77c\uc218\ub85d \uc0dd\uac01\uc774 \ub9ce\uc544\uc838 \uc815\uc791 \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294 \ud568\uc815\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uc870\uc5b8\uc744 \ub4e3\ub294 \ub370\uc11c \uba48\ucd94\uc9c0 \ub9d0\uace0, \ub4e4\uc740 \uac83 \uc911 \ud558\ub098\ub294 \uc624\ub298 \uc548\uc5d0 \uc2e4\ud589\uc73c\ub85c \uc62e\uae30\uc138\uc694. \ubc30\uc6b0\ub294 \uc790\ub9ac, \uc0c1\ub2f4\ubc1b\ub294 \uc790\ub9ac, \uac80\uc9c4\uc774\ub098 \uc810\uac80\ucc98\ub7fc \ub0a8\uc758 \uc190\uc744 \ube4c\ub9ac\ub294 \uc77c\uc815\uc744 \uc7a1\uae30\uc5d0 \uc54c\ub9de\uc2b5\ub2c8\ub2e4. \uc800\ub141\uc5d0\ub294 \ubc1b\uc740 \uac83\uc744 \ud55c \uc904\uc774\ub77c\ub3c4 \uae30\ub85d\ud574 \ub450\uba74 \uc774 \uae30\uc6b4\uc774 \ub0b4\uc77c\ub85c \uc774\uc5b4\uc9d1\ub2c8\ub2e4.',wealth:'\ub4e4\uc5b4\uc624\ub294 \ub3c8\ubcf4\ub2e4 \uc544\uaef4\uc9c0\ub294 \ub3c8\uc774 \uc0dd\uae30\ub294 \ub0a0\uc785\ub2c8\ub2e4. \ub204\uad70\uac00\uc758 \uadc0\ub754\uc73c\ub85c \ubd88\ud544\uc694\ud55c \uc9c0\ucd9c\uc744 \ud53c\ud558\uac70\ub098, \uc78a\uace0 \uc788\ub358 \ud658\uae09\uc774\ub098 \ud61c\ud0dd\uc744 \ucc59\uae30\uac8c \ub429\ub2c8\ub2e4. \ud070 \ud22c\uc790\ub294 \uacb0\uc815\ud558\uc9c0 \ub9d0\uace0 \uc815\ubcf4\ub9cc \ubaa8\uc73c\uc138\uc694.',love:'\uba3c\uc800 \ub2e4\uac00\uc624\ub294 \uc0ac\ub78c\uc774 \uc788\uc2b5\ub2c8\ub2e4. \ud3c9\uc18c\ub77c\uba74 \ud758\ub824\ubcf4\ub0c8\uc744 \uc548\ubd80 \uc5f0\ub77d\uc5d0 \uc815\uc131\uaecf \ub2f5\ud574 \ubcf4\uc138\uc694. \ucee4\ud50c\uc774\ub77c\uba74 \uc0c1\ub300\uc758 \uc870\uc5b8\uc744 \uc794\uc18c\ub9ac\ub85c \ub4e3\uc9c0 \uc54a\ub294 \uac83\ub9cc\uc73c\ub85c \uad00\uacc4\uac00 \ubd80\ub4dc\ub7ec\uc6cc\uc9d1\ub2c8\ub2e4.',work:'\ud63c\uc790 \ub059\ub059\ub300\ub358 \ubb38\uc81c\ub97c \ub3d9\ub8cc\ub098 \uc0c1\uc0ac\uc5d0\uac8c \uc5f4\uc5b4 \ubcf4\uc774\uba74 \uc758\uc678\ub85c \ube60\ub974\uac8c \ud480\ub9bd\ub2c8\ub2e4. \ub3c4\uc6c0\uc744 \uccad\ud558\ub294 \uac83\uc774 \uc57d\uc810\uc774 \uc544\ub2c8\ub77c \uc624\ub298\uc758 \uc804\ub7b5\uc785\ub2c8\ub2e4. \ud68c\uc758\uc5d0\uc11c\ub294 \ub9d0\ud558\uae30\ubcf4\ub2e4 \ub4e3\uae30\uc5d0 \ube44\uc911\uc744 \ub450\uc138\uc694.',health:'\ubab8\uc774 \uc26c\uace0 \uc2f6\uc5b4 \ud558\ub294 \uc2e0\ud638\ub97c \ubb34\uc2dc\ud558\uc9c0 \ub9c8\uc138\uc694. \uc624\ub798 \ubbf8\ub8ec \uac80\uc9c4\uc774\ub098 \uce58\ub8cc \uc608\uc57d\uc744 \uc7a1\uae30\uc5d0 \uc88b\uc740 \ub0a0\uc785\ub2c8\ub2e4. \ub530\ub73b\ud55c \uc74c\uc2dd\uacfc \uc774\ub978 \ucde8\uce68\uc774 \ub0b4\uc77c\uc758 \ucee8\ub514\uc158\uc744 \ub9cc\ub4ed\ub2c8\ub2e4.',study:'\ud63c\uc790 \ucc45\uacfc \uc528\ub984\ud558\uae30\ubcf4\ub2e4 \uc124\uba85\uc744 \ub4e3\ub294 \uacf5\ubd80\uac00 \uc798 \ub4e4\uc5b4\uc635\ub2c8\ub2e4. \uac15\uc758, \uc2a4\ud130\ub514, \uc9c8\ubb38\ud558\uae30\uc5d0 \uc2dc\uac04\uc744 \uc4f0\uc138\uc694. \uc774\ud574\uac00 \ub9c9\ud78c \uacf3\uc744 \uc9c8\ubb38 \ud55c \uc904\ub85c \uc815\ub9ac\ud574 \ubcf4\ub0b4\ub294 \uac83\ub9cc\uc73c\ub85c \ubc18\uc740 \ud480\ub9bd\ub2c8\ub2e4.',lucky:{color:'\ubca0\uc774\uc9c0',food:'\ub41c\uc7a5\ucc0c\uac1c',number:'3,8',person:'\uc120\ubc30',direction:'\ubd81\ub3d9\ucabd',item:'\uc190\uc218\uac74'},tip:'\ud3b8\uc548\ud568\uc744 \uc785\ub294 \ucf54\ub514\n\uc624\ub298\uc740 \ud798\uc744 \ube7c\ub294 \uac83\uc774 \uc6b4\uc744 \ubd80\ub985\ub2c8\ub2e4. \ubca0\uc774\uc9c0\ub098 \ud06c\ub9bc\uc0c9 \uc0c1\uc758\ucc98\ub7fc \ubd80\ub4dc\ub7ec\uc6b4 \uc0c9\uc774 \uc0c1\ub300\uc758 \uacbd\uacc4\ub97c \ud480\uace0 \ub3c4\uc6c0\uc744 \ub04c\uc5b4\uc635\ub2c8\ub2e4. \ub531 \ub5a8\uc5b4\uc9c0\ub294 \uc815\uc7a5\ubcf4\ub2e4 \ub2c8\ud2b8\ub098 \uac00\ub514\uac74\ucc98\ub7fc \ud488\uc774 \uc788\ub294 \uc637\uc774 \uc5b4\uc6b8\ub9ac\uace0, \uc190\uc218\uac74\uc774\ub098 \uc791\uc740 \ub178\ud2b8\ucc98\ub7fc \ubc1b\uc740 \uac83\uc744 \ub2f4\uc544\ub458 \uc18c\ud488\uc744 \ud558\ub098 \ucc59\uae30\uba74 \ubc1b\uc740 \ubcf5\uc774 \ud769\uc5b4\uc9c0\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.'},wealth:{score:72,headline:'\uadf8\ubb3c\uc744 \uac70\ub450\ub294 \uc5b4\ubd80\ucc98\ub7fc \uacb0\uacfc\uac00 \uc190\uc5d0 \uc7a1\ud788\ub294 \ud558\ub8e8\uc785\ub2c8\ub2e4.',overall:'\uc624\ub298\uc740 \ubfcc\ub824\ub454 \uac83\uc744 \uac70\ub450\ub294 \ub0a0\uc785\ub2c8\ub2e4. \ubbf8\ub904\ub454 \uc815\uc0b0, \ubc00\ub9b0 \ub2f5\uc7a5, \uacb0\ub860\uc744 \ub0b4\uc57c \ud560 \uc77c\uc744 \uc624\ub298 \ucc98\ub9ac\ud558\uba74 \uc720\ub09c\ud788 \ub9e4\ub4ed\uc774 \uc798 \uc9c0\uc5b4\uc9d1\ub2c8\ub2e4. \ub2e4\ub9cc \uac70\ub450\ub294 \ub0a0\uc5d0\ub294 \uc695\uc2ec\ub3c4 \ud568\uaed8 \ucee4\uc9d1\ub2c8\ub2e4. \ud558\ub098\ub97c \uc5bb\uace0 \ub458\uc744 \ubc14\ub77c\uba74 \ucc98\uc74c \uac83\uae4c\uc9c0 \ub193\uce58\ub294 \ud615\uc0c1\uc774\ub2c8, \uc624\ub298\uc758 \ubaa9\ud45c\ub97c \uc544\uce68\uc5d0 \ud558\ub098\ub9cc \uc815\ud558\uace0 \uadf8\uac83\ub9cc \ub05d\ub0b4\uc138\uc694. \ub3c8\uacfc \uad00\ub828\ub41c \uc57d\uc18d\uc740 \ubb38\uc11c\ub85c \ub0a8\uae30\uace0, \uc0ac\ub78c\uc5d0\uac8c \ubca0\ud47c \uac83\uc740 \ub3cc\ub824\ubc1b\uc744 \uc0dd\uac01\uc744 \uc811\uc73c\uba74 \uc624\ud788\ub824 \ub354 \ud070 \uac83\uc774 \ub3cc\uc544\uc635\ub2c8\ub2e4. \uc800\ub141\uc5d0\ub294 \uc791\uc740 \uac83\uc774\ub77c\ub3c4 \uc2a4\uc2a4\ub85c\uc5d0\uac8c \ubcf4\uc0c1\uc744 \uc8fc\uc138\uc694. \uac70\ub454 \uac83\uc744 \ubab8\uc774 \uae30\uc5b5\ud574\uc57c \ub2e4\uc74c \uc218\ud655\uc774 \uc635\ub2c8\ub2e4.',wealth:'\ud604\uc2e4\uc801\uc778 \uc774\uc775\uc774 \uc0dd\uae30\ub294 \ub0a0\uc785\ub2c8\ub2e4. \ubc1b\uc744 \ub3c8\uc774 \uc788\ub2e4\uba74 \uc624\ub298 \uc815\uc911\ud558\uac8c \ub9d0\ud558\uc138\uc694. \ud560\uc778\uc774\ub098 \uc870\uac74 \ud611\uc0c1\ub3c4 \uc720\ub9ac\ud558\uac8c \ud750\ub985\ub2c8\ub2e4. \ub2e8, \ucda9\ub3d9\uad6c\ub9e4\ub294 \uc624\ub298 \ubc88 \uac83\uc744 \uadf8\ub300\ub85c \ud758\ub824\ubcf4\ub0c5\ub2c8\ub2e4.',love:'\ub9c8\uc74c\uc744 \ud655\uc778\ud558\uae30 \uc88b\uc740 \ub0a0\uc785\ub2c8\ub2e4. \uc560\ub9e4\ud558\uac8c \ub04c\uc5b4\uc628 \uad00\uacc4\ub77c\uba74 \uc624\ub298 \uac00\ubcbc\uc6b4 \uc57d\uc18d \ud558\ub098\ub97c \uc7a1\uc544 \ubcf4\uc138\uc694. \ucee4\ud50c\uc740 \ud568\uaed8 \ub3c8 \uc4f0\ub294 \uacc4\ud68d, \uc5ec\ud589\uc774\ub098 \uc678\uc2dd \uc774\uc57c\uae30\uac00 \uad00\uacc4\ub97c \ub370\uc6c1\ub2c8\ub2e4.',work:'\uc131\uacfc\uac00 \ub208\uc5d0 \ubcf4\uc774\ub294 \ub0a0\uc785\ub2c8\ub2e4. \ubcf4\uace0\uc640 \ubc1c\ud45c, \ub9c8\uac10\uc5d0 \ud798\uc744 \uc2e4\uc73c\uc138\uc694. \uc22b\uc790\ub85c \ub9d0\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc22b\uc790\ub85c \ub9d0\ud558\uba74 \uc124\ub4dd\uc774 \ube60\ub985\ub2c8\ub2e4. \uc0c8 \uc77c\uc744 \ubc8c\uc774\uae30\ubcf4\ub2e4 \ud558\ub358 \uc77c\uc744 \ub05d\ub0b4\ub294 \ub370 \uc9d1\uc911\ud558\uc138\uc694.',health:'\uc77c\uc5d0 \ubab0\ub450\ud558\ub2e4 \ub07c\ub2c8\ub97c \uac70\ub974\uae30 \uc26c\uc6b4 \ub0a0\uc785\ub2c8\ub2e4. \uc810\uc2ec\uc740 \ubc18\ub4dc\uc2dc \ucc59\uae30\uace0 \ubb3c\uc744 \ud3c9\uc18c\ubcf4\ub2e4 \ud55c \uc794 \ub354 \ub9c8\uc2dc\uc138\uc694. \uc800\ub141 \ub2a6\uc740 \uacfc\uc2dd\ub9cc \ud53c\ud558\uba74 \ucee8\ub514\uc158\uc740 \uc88b\uac8c \uc720\uc9c0\ub429\ub2c8\ub2e4.',study:'\ubb38\uc81c\ub97c \ud478\ub294 \uacf5\ubd80\uac00 \uc798 \ub418\ub294 \ub0a0\uc785\ub2c8\ub2e4. \uac1c\ub150\uc744 \uc0c8\ub85c \uc77d\uae30\ubcf4\ub2e4 \uae30\ucd9c\uc774\ub098 \uc5f0\uc2b5 \ubb38\uc81c\ub85c \uc810\uac80\ud558\uc138\uc694. \ud2c0\ub9b0 \ubb38\uc81c\ub97c \uc624\ub298 \uc548\uc5d0 \ub2e4\uc2dc \ud480\uba74 \uae30\uc5b5\uc5d0 \uc624\ub798 \ub0a8\uc2b5\ub2c8\ub2e4.',lucky:{color:'\ub178\ub780\uc0c9',food:'\ubd88\uace0\uae30',number:'5,9',person:'\uac70\ub798\ucc98 \uc0ac\ub78c',direction:'\ub0a8\ucabd',item:'\uc9c0\uac11'},tip:'\uacb0\uacfc\ub97c \ubd80\ub974\ub294 \ucf54\ub514\n\ub178\ub780\uc0c9\uc774\ub098 \uae08\uc0c9 \ud3ec\uc778\ud2b8\uac00 \uc624\ub298\uc758 \uc7ac\ubb3c\uc6b4\uc744 \ubc1b\uccd0\uc90d\ub2c8\ub2e4. \uc804\uccb4\ub97c \ud654\ub824\ud558\uac8c \uc785\uae30\ubcf4\ub2e4 \uc2dc\uacc4, \ubc18\uc9c0, \uac00\ubc29 \uc7a5\uc2dd\ucc98\ub7fc \uc791\uc740 \ubd80\ubd84\uc5d0 \uae08\ube5b\uc744 \ub450\uc138\uc694. \uc9c0\uac11\uc740 \uc815\ub9ac\ud574\uc11c \ub4e4\uace0 \ub098\uac00\uba74 \ub4e4\uc5b4\uc624\ub294 \ub3c8\uc758 \uc790\ub9ac\uac00 \uc0dd\uae41\ub2c8\ub2e4. \ub2e8\uc815\ud55c \uc154\uce20\ucc98\ub7fc \ubbff\uc74c\uc744 \uc8fc\ub294 \ucc28\ub9bc\uc774 \ud611\uc0c1\uacfc \uac70\ub798\uc5d0 \ud798\uc774 \ub429\ub2c8\ub2e4.'},output:{score:64,headline:'\ubd04\ubc14\ub78c\uc5d0 \uaf43\uc78e \ub0a0\ub9ac\ub4ef \ub9d0\uacfc \uc7ac\uc8fc\uac00 \ubc16\uc73c\ub85c \ud769\uc5b4\uc9c0\ub294 \ud558\ub8e8\uc785\ub2c8\ub2e4.',overall:'\uc624\ub298\uc740 \ud45c\ud604\uc774 \uc798 \ub418\ub294 \ub0a0\uc785\ub2c8\ub2e4. \uae00\uc774 \uc368\uc9c0\uace0 \ub9d0\uc774 \ud1b5\ud558\uace0 \uc544\uc774\ub514\uc5b4\uac00 \uc0d8\uc19f\uc2b5\ub2c8\ub2e4. \uc0ac\ub78c\ub4e4 \uc55e\uc5d0 \uc11c\ub294 \uc77c, \uc81c\uc548\ud558\ub294 \uc77c, \ub9cc\ub4dc\ub294 \uc77c\uc5d0 \uc88b\uc2b5\ub2c8\ub2e4. \uadf8\ub7f0\ub370 \ub098\uac00\ub294 \uae30\uc6b4\uc774 \ub9ce\uc740 \ub0a0\uc740 \uadf8\ub9cc\ud07c \uc0c8\uae30\ub3c4 \ud569\ub2c8\ub2e4. \ub9d0\uc774 \uc55e\uc11c \uc57d\uc18d\uc744 \ub0a8\ubc1c\ud558\uac70\ub098, \uc7ac\ubbf8\uc5d0 \ub04c\ub824 \ud574\uc57c \ud560 \uc77c\uc744 \ub4a4\ub85c \ubbf8\ub8e8\uae30 \uc27d\uc2b5\ub2c8\ub2e4. \uc2dc\uc791\uc740 \uac00\ubccd\uac8c \ud558\ub418 \ub9c8\ubb34\ub9ac\ub97c \ub204\uac00 \ud560\uc9c0 \uba3c\uc800 \uc815\ud558\uc138\uc694. \uc624\ub298 \ud55c \ub9d0 \uc911 \uc9c0\ucf1c\uc57c \ud560 \uac83\uc740 \uba54\ubaa8\ud574 \ub450\uace0, \uc800\ub141\uc5d0\ub294 \ud63c\uc790 \uc788\ub294 \uc2dc\uac04\uc744 \uc9e7\uac8c\ub77c\ub3c4 \uac00\uc838 \ud769\uc5b4\uc9c4 \uae30\uc6b4\uc744 \uac70\ub450\uc138\uc694. \uadf8\ub7ec\uba74 \uc624\ub298\uc758 \ubc1c\uc0b0\uc774 \ub0b4\uc77c\uc758 \uacb0\uacfc\ub85c \uc774\uc5b4\uc9d1\ub2c8\ub2e4.',wealth:'\uc4f0\ub294 \uc990\uac70\uc6c0\uc774 \ucee4\uc9c0\ub294 \ub0a0\uc785\ub2c8\ub2e4. \uc0ac\ub78c \ub9cc\ub098\uace0 \uba39\uace0 \uc990\uae30\ub294 \uc9c0\ucd9c\uc774 \ub298\uc5b4\ub098\ub2c8 \uc0c1\ud55c\uc120\uc744 \uc544\uce68\uc5d0 \uc815\ud558\uc138\uc694. \uc7ac\ub2a5\uc73c\ub85c \ubc84\ub294 \ub3c8, \ubd80\uc5c5\uc774\ub098 \uc81c\uc548\uc5d0\ub294 \uae38\uc774 \uc5f4\ub9bd\ub2c8\ub2e4.',love:'\ub9e4\ub825\uc774 \ub4dc\ub7ec\ub098\ub294 \ub0a0\uc785\ub2c8\ub2e4. \uc194\ub85c\ub77c\uba74 \ubaa8\uc784\uc5d0 \ub098\uac00 \ubcf4\uc138\uc694. \ub9d0 \ud55c\ub9c8\ub514\uac00 \uc778\uc5f0\uc744 \ub9cc\ub4ed\ub2c8\ub2e4. \ucee4\ud50c\uc740 \uc990\uac70\uc6b4 \ub300\ud654\uac00 \ub118\uce58\uc9c0\ub9cc, \ub18d\ub2f4\uc774 \uc120\uc744 \ub118\uc9c0 \uc54a\ub3c4\ub85d \uc0c1\ub300 \ud45c\uc815\uc744 \uc0b4\ud53c\uc138\uc694.',work:'\uae30\ud68d\uacfc \ubc1c\ud45c, \uc81c\uc548\uc11c\uc5d0 \uac15\ud55c \ub0a0\uc785\ub2c8\ub2e4. \ub5a0\uc624\ub978 \uc544\uc774\ub514\uc5b4\ub294 \ubc14\ub85c \uc801\uc5b4 \ub450\uc138\uc694. \ub2e4\ub9cc \uc0c1\uc0ac\uc758 \uc9c0\uc2dc\ub97c \uac00\ubccd\uac8c \ub118\uae30\uac70\ub098 \uaddc\uce59\uc744 \uac74\ub108\ub6f0\uba74 \ub4a4\ud0c8\uc774 \uc788\uc2b5\ub2c8\ub2e4. \ucc3d\uc758\uc131\uc740 \ud2c0 \uc548\uc5d0\uc11c \ube5b\ub0a9\ub2c8\ub2e4.',health:'\uc5d0\ub108\uc9c0\ub97c \ub9ce\uc774 \uc4f0\ub294 \ub0a0\uc774\ub77c \uc800\ub141\uc5d0 \uae09\uaca9\ud788 \uc9c0\uce60 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubaa9\uc744 \ub9ce\uc774 \uc4f0\uba74 \ub530\ub73b\ud55c \ubb3c\uc744 \uc790\uc8fc \ub9c8\uc2dc\uace0, \ud765\ubd84\ud574\uc11c \ub2a6\uac8c \uc790\uc9c0 \uc54a\ub3c4\ub85d \ucde8\uce68 \uc2dc\uac04\uc744 \ubbf8\ub9ac \uc815\ud574 \ub450\uc138\uc694.',study:'\ubc30\uc6b4 \uac83\uc744 \ub9d0\ub85c \uc124\uba85\ud574 \ubcf4\ub294 \uacf5\ubd80\uac00 \ud6a8\uacfc\uc801\uc785\ub2c8\ub2e4. \uce5c\uad6c\uc5d0\uac8c \uac00\ub974\uccd0 \uc8fc\uac70\ub098 \uc18c\ub9ac \ub0b4\uc5b4 \uc815\ub9ac\ud558\uc138\uc694. \uc0c8 \uacfc\ubaa9\uc744 \ubc8c\uc774\uae30\ubcf4\ub2e4 \uc9c0\uae08 \ud558\ub294 \uac83\uc744 \uae4a\uac8c \ud30c\ub294 \ud3b8\uc774 \ub0ab\uc2b5\ub2c8\ub2e4.',lucky:{color:'\uc5f0\ub450\uc0c9',food:'\uae40\ubc25',number:'2,7',person:'\ub3d9\uc0dd\ubed8 \ud6c4\ubc30',direction:'\ub3d9\ucabd',item:'\ud39c'},tip:'\uac00\ubccd\uac8c \ube5b\ub098\ub294 \ucf54\ub514\n\uc5f0\ub450\ub098 \ubbfc\ud2b8\ucc98\ub7fc \uc0b0\ub73b\ud55c \uc0c9\uc774 \uc624\ub298\uc758 \ud45c\ud604\ub825\uc744 \uc0b4\ub9bd\ub2c8\ub2e4. \ubb34\uac70\uc6b4 \uac89\uc637\ubcf4\ub2e4 \uc6c0\uc9c1\uc774\uae30 \ud3b8\ud55c \ucc28\ub9bc\uc774 \uc88b\uace0, \ub9d0\uc744 \ub9ce\uc774 \ud558\ub294 \ub0a0\uc774\ub2c8 \ubaa9\uc744 \uac10\uc2f8\ub294 \uc2a4\uce74\ud504\ub098 \uac00\ubcbc\uc6b4 \ubaa9\uac78\uc774\ub85c \ubaa9 \ubd80\ubd84\uc5d0 \ud3ec\uc778\ud2b8\ub97c \ub450\uc138\uc694. \ud39c \ud558\ub098\ub97c \uaf2d \ucc59\uae30\uc138\uc694. \ub5a0\uc624\ub978 \uac83\uc744 \ubc14\ub85c \uc801\ub294 \uc2b5\uad00\uc774 \uc624\ub298\uc758 \uc7ac\uc8fc\ub97c \uacb0\uacfc\ub85c \ubc14\uafc9\ub2c8\ub2e4.'},self:{score:52,headline:'\uac19\uc740 \uae38\uc744 \uac00\ub294 \uc0ac\ub78c\uc774 \ub9ce\uc544 \uc5b4\uae68\uac00 \ubd80\ub52a\ud788\ub294 \ud558\ub8e8\uc785\ub2c8\ub2e4.',overall:'\uc624\ub298\uc740 \ub098\uc640 \ub2ee\uc740 \uae30\uc6b4\uc774 \uacb9\uce58\ub294 \ub0a0\uc785\ub2c8\ub2e4. \uc8fc\uad00\uc774 \ub69c\ub837\ud574\uc9c0\uace0 \ucd94\uc9c4\ub825\uc774 \uc0dd\uae30\uc9c0\ub9cc, \uadf8\ub9cc\ud07c \uc591\ubcf4\uac00 \uc5b4\ub824\uc6cc\uc9c0\uace0 \uacbd\uc7c1\uc790\uac00 \ub208\uc5d0 \ub4e4\uc5b4\uc635\ub2c8\ub2e4. \uc791\uc740 \uc758\uacac \ucc28\uc774\uac00 \uc790\uc874\uc2ec \uc2f8\uc6c0\uc73c\ub85c \ubc88\uc9c0\uae30 \uc26c\uc6b0\ub2c8, \uc774\uae30\ub294 \uac83\ubcf4\ub2e4 \ub05d\ub0b4\ub294 \uac83\uc744 \ubaa9\ud45c\ub85c \uc0bc\uc73c\uc138\uc694. \ub098\ub220\uc57c \ud560 \uc77c\uc774 \uc0dd\uae30\uba74 \uba3c\uc800 \ub098\ub204\ub294 \ucabd\uc774 \uacb0\uad6d \ub354 \ub9ce\uc774 \uac00\uc838\uac11\ub2c8\ub2e4. \ud63c\uc790 \ubc00\uc5b4\ubd99\uc774\ub294 \ud798\uc740 \uc88b\uc9c0\ub9cc \ub0a8\uc758 \ubaab\uae4c\uc9c0 \ub5a0\uc548\uc9c0 \ub9c8\uc138\uc694. \uc624\ub298\uc758 \uacbd\uc7c1\uc740 \uc801\uc774 \uc544\ub2c8\ub77c \uc790\uadf9\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\uba74 \uc131\uc7a5\uc758 \uc7ac\ub8cc\uac00 \ub429\ub2c8\ub2e4. \uc800\ub141\uc5d0\ub294 \uac00\uae4c\uc6b4 \uce5c\uad6c\uc640 \uac00\ubcbc\uc6b4 \ub300\ud654\ub85c \ub0a0 \uc120 \ub9c8\uc74c\uc744 \ud480\uc5b4 \uc8fc\uc138\uc694.',wealth:'\ub098\uac00\ub294 \ub3c8\uc774 \uc0dd\uae30\ub294 \ub0a0\uc785\ub2c8\ub2e4. \ub354\uce58\ud398\uc774, \uacbd\uc870\uc0ac, \ub3d9\ub8cc\uc640\uc758 \uc2dd\uc0ac\ucc98\ub7fc \uc0ac\ub78c\uc5d0 \uc4f0\ub294 \uc9c0\ucd9c\uc774 \ub298\uc5b4\ub0a9\ub2c8\ub2e4. \uc544\uae4c\uc6cc\ud558\uc9c0 \ub9d0\ub418 \ube4c\ub824\uc8fc\ub294 \ub3c8\uc740 \uc624\ub298 \ud53c\ud558\uc138\uc694. \ub3cc\ub824\ubc1b\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.',love:'\uace0\uc9d1\uc774 \uc138\uc9c0\ub294 \ub0a0\uc774\ub77c \uc0ac\uc18c\ud55c \ub9d0\ub2e4\ud23c\uc744 \uc870\uc2ec\ud558\uc138\uc694. \uc0c1\ub300\uc758 \uc758\uacac\uc744 \ub05d\uae4c\uc9c0 \ub4e3\ub294 \uac83\ub9cc\uc73c\ub85c \ubc18\uc740 \uc774\uae41\ub2c8\ub2e4. \uc194\ub85c\ub294 \uacbd\uc7c1\uc790\uac00 \uc788\ub294 \uad00\uacc4\uc5d0 \ub9c8\uc74c\uc744 \uc4f0\uae30\ubcf4\ub2e4 \uc790\uc2e0\uc5d0\uac8c \uc9d1\uc911\ud558\ub294 \ud3b8\uc774 \ub0ab\uc2b5\ub2c8\ub2e4.',work:'\ub3d9\ub8cc\uc640 \uc5ed\ud560\uc774 \uacb9\uce58\uac70\ub098 \uacf5\uc774 \ub098\ub258\ub294 \uc0c1\ud669\uc774 \uc0dd\uae41\ub2c8\ub2e4. \ub0b4 \ubaab\uc744 \ubd84\uba85\ud788 \ud558\ub418 \uba3c\uc800 \uc591\ubcf4\ud560 \uc218 \uc788\ub294 \uc791\uc740 \uac83\uc744 \uc815\ud574 \ub450\uc138\uc694. \ud63c\uc790 \uacb0\uc815\ud558\uae30\ubcf4\ub2e4 \ud55c \ubc88 \ub354 \ud655\uc778\ud558\uba74 \uc2e4\uc218\ub97c \uc904\uc785\ub2c8\ub2e4.',health:'\ud798\uc774 \ub118\uccd0 \ubb34\ub9ac\ud558\uae30 \uc26c\uc6b4 \ub0a0\uc785\ub2c8\ub2e4. \uc6b4\ub3d9\uc740 \uc88b\uc9c0\ub9cc \uacbd\uc7c1\uc801\uc73c\ub85c \ud558\uba74 \ub2e4\uce69\ub2c8\ub2e4. \uc5b4\uae68\uc640 \ubaa9\uc758 \uae34\uc7a5\uc744 \uc790\uc8fc \ud480\uc5b4 \uc8fc\uace0, \ud654\uac00 \uc62c\ub77c\uc62c \ub54c\ub294 \ucc2c\ubb3c \ud55c \uc794\uc73c\ub85c \uc2dd\ud788\uc138\uc694.',study:'\ub77c\uc774\ubc8c\uc774 \uc790\uadf9\uc774 \ub418\ub294 \ub0a0\uc785\ub2c8\ub2e4. \ud63c\uc790\ubcf4\ub2e4 \ud568\uaed8 \uacf5\ubd80\ud558\uba74 \uc9d1\uc911\uc774 \uc624\ub798\uac11\ub2c8\ub2e4. \ube44\uad50\uc5d0 \ud754\ub4e4\ub9ac\uc9c0 \ub9d0\uace0 \uc5b4\uc81c\uc758 \ub098\uc640\ub9cc \ube44\uad50\ud558\uc138\uc694. \uc791\uc740 \ubaa9\ud45c\ub97c \ub05d\uae4c\uc9c0 \uc644\uc218\ud558\ub294 \uac83\uc774 \uc624\ub298\uc758 \uacfc\uc81c\uc785\ub2c8\ub2e4.',lucky:{color:'\ud770\uc0c9',food:'\ub0c9\uba74',number:'1,6',person:'\uc624\ub79c \uce5c\uad6c',direction:'\uc11c\ucabd',item:'\uc2dc\uacc4'},tip:'\ub0a0\uc744 \uc138\uc6b0\uc9c0 \uc54a\ub294 \ucf54\ub514\n\ud770\uc0c9\uc774\ub098 \ubc1d\uc740 \ud68c\uc0c9\ucc98\ub7fc \uae68\ub057\ud55c \uc0c9\uc774 \uc624\ub298\uc758 \ub0a0\uce74\ub85c\uc6c0\uc744 \uc911\ud654\ud569\ub2c8\ub2e4. \uac15\ud55c \uc6d0\uc0c9\uc774\ub098 \ud070 \ub85c\uace0\ub294 \uc0c1\ub300\ub97c \uc790\uadf9\ud558\ub2c8 \ud53c\ud558\uc138\uc694. \uc190\ubaa9\uc5d0 \uc2dc\uacc4\ub97c \ucc28\uba74 \uc2dc\uac04 \uc57d\uc18d\uacfc \uc790\uae30 \ud1b5\uc81c\uc758 \uae30\uc6b4\uc774 \uc0dd\uaca8 \ucda9\ub3cc\uc744 \uc904\uc785\ub2c8\ub2e4. \uc2e0\ubc1c\uc740 \ud3b8\ud55c \uac83\uc73c\ub85c, \uc624\ub798 \uc11c \uc788\uac70\ub098 \uac77\ub294 \uc77c\uc774 \uc0dd\uae38 \uc218 \uc788\uc2b5\ub2c8\ub2e4.'},pressure:{score:34,headline:'\ubb34\uac70\uc6b4 \uc9d0\uc744 \uc9c0\uace0 \ube44\ud0c8\uae38\uc744 \uc624\ub974\ub294 \ub4ef\ud55c \ud558\ub8e8\uc785\ub2c8\ub2e4.',overall:'\uc624\ub298\uc740 \ub098\ub97c \ub204\ub974\ub294 \uae30\uc6b4\uc774 \ub4e4\uc5b4\uc624\ub294 \ub0a0\uc785\ub2c8\ub2e4. \ucc45\uc784\uc774 \ub298\uace0 \uc9c0\uc801\uc774 \ub530\ub974\uba70 \uc77c\uc815\uc774 \ube61\ube61\ud558\uac8c \ubc00\ub824\uc635\ub2c8\ub2e4. \ub9c8\uc74c\uc774 \uba3c\uc800 \uc9c0\uce58\uba74 \uc2e4\uc218\uac00 \uc774\uc5b4\uc9c0\uace0, \uc2e4\uc218 \ud558\ub098\uac00 \uc2e0\ub8b0\uae4c\uc9c0 \ud754\ub4e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc0c8 \uc77c\uc744 \ubc8c\uc774\uc9c0 \ub9d0\uace0 \uc9c0\uae08 \ub9e1\uc740 \uac83\uc744 \uae30\ud55c \uc548\uc5d0 \ub9c8\ubb34\ub9ac\ud558\ub294 \ub370\ub9cc \uc9d1\uc911\ud558\uc138\uc694. \uc717\uc0ac\ub78c\uc758 \ub9d0\uc740 \ubc18\ubc15\ud558\uc9c0 \ub9d0\uace0 \uc77c\ub2e8 \ubc1b\uc544 \uc801\uc740 \ub4a4 \ub0b4\uc77c \ub2f5\ud558\uc138\uc694. \uc5b5\uc6b8\ud55c \uc77c\uc774 \uc788\uc5b4\ub3c4 \uc624\ub298 \ub530\uc9c0\uba74 \uc190\ud574\uc785\ub2c8\ub2e4. \ubaa8\uc544\ub454 \uc6b4\uc774 \uc788\ub2e4\uba74 \uc624\ub298 \uc4f0\ub294 \ub0a0\uc785\ub2c8\ub2e4. \uc800\ub141\uc5d0\ub294 \uc77c\ucc0d \uc9d1\uc5d0 \ub4e4\uc5b4\uac00 \ubab8\uc744 \ub530\ub73b\ud558\uac8c \ud558\uace0, \ud798\ub4e0 \ud558\ub8e8\ub97c \ubc84\ud2f4 \uc790\uc2e0\uc744 \uc778\uc815\ud574 \uc8fc\uc138\uc694. \ub20c\ub9b0 \ub9cc\ud07c \ub2e8\ub2e8\ud574\uc9c0\ub294 \ub0a0\uc785\ub2c8\ub2e4.',wealth:'\uc608\uc0c1 \ubc16\uc758 \uc9c0\ucd9c\uc774 \uc0dd\uae30\uae30 \uc27d\uc2b5\ub2c8\ub2e4. \ubc8c\uae08, \uc218\ub9ac\ube44, \uac11\uc791\uc2a4\ub7ec\uc6b4 \uacbd\uc870\uc0ac \uac19\uc740 \ub3c8\uc785\ub2c8\ub2e4. \ud070 \uacb0\uc81c\uc640 \uacc4\uc57d\uc740 \ud558\ub8e8\ub9cc \ubbf8\ub8e8\uc138\uc694. \uc624\ub298 \uc11c\uba85\ud558\ub294 \ubb38\uc11c\ub294 \ub450 \ubc88 \uc77d\uc5b4\uc57c \ud569\ub2c8\ub2e4.',love:'\uc0c1\ub300\uc758 \ub9d0\uc774 \ud3c9\uc18c\ubcf4\ub2e4 \uc544\ud504\uac8c \ub4e4\ub9ac\ub294 \ub0a0\uc785\ub2c8\ub2e4. \uc0c1\ucc98\ubc1b\uc744 \uc218 \uc788\uc73c\ub2c8 \uc911\uc694\ud55c \ub300\ud654\ub294 \ud53c\ud558\uace0, \uaf2d \ud574\uc57c \ud55c\ub2e4\uba74 \uae00\ubcf4\ub2e4 \ubaa9\uc18c\ub9ac\ub85c \ud558\uc138\uc694. \ud63c\uc790 \uc0ad\uc774\uc9c0 \ub9d0\uace0 \uac00\uae4c\uc6b4 \uc0ac\ub78c\uc5d0\uac8c \ud138\uc5b4\ub193\uc73c\uba74 \uac00\ubcbc\uc6cc\uc9d1\ub2c8\ub2e4.',work:'\uc555\ubc15\uc774 \uac00\uc7a5 \ud06c\uac8c \ub290\uaef4\uc9c0\ub294 \uc601\uc5ed\uc785\ub2c8\ub2e4. \uc9c0\uc801\uc774\ub098 \ucc45\uc784 \ucd94\uad81\uc774 \uc788\uc744 \uc218 \uc788\uc9c0\ub9cc \ubcc0\uba85\ubcf4\ub2e4 \uc218\uc2b5\uc774 \uba3c\uc800\uc785\ub2c8\ub2e4. \uc6b0\uc120\uc21c\uc704\ub97c \uc138 \uac1c\ub85c \uc904\uc774\uace0 \ud558\ub098\uc529 \ub05d\ub0b4\uc138\uc694. \uc644\ubcbd\ubcf4\ub2e4 \uc81c\uc2dc\uac04\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.',health:'\uae34\uc7a5\uc774 \ubab8\uc73c\ub85c \ub098\ud0c0\ub098\ub294 \ub0a0\uc785\ub2c8\ub2e4. \ub450\ud1b5, \uc18c\ud654\ubd88\ub7c9, \uc5b4\uae68 \uacb0\ub9bc\uc744 \uc870\uc2ec\ud558\uc138\uc694. \uce74\ud398\uc778\uc744 \uc904\uc774\uace0 \uc810\uc2ec\uc5d0 10\ubd84\uc774\ub77c\ub3c4 \uac78\uc73c\uc138\uc694. \uc624\ub298\uc740 \uc57c\uadfc\ubcf4\ub2e4 \uc218\uba74\uc774 \ub0b4\uc77c\uc744 \uc0b4\ub9bd\ub2c8\ub2e4.',study:'\uc9d1\uc911\uc774 \ud750\ud2b8\ub7ec\uc9c0\uace0 \uc678\ubd80 \uc694\uad6c\uac00 \ub9ce\uc740 \ub0a0\uc785\ub2c8\ub2e4. \uacc4\ud68d\uc744 \uc904\uc5ec \uaf2d \ud574\uc57c \ud560 \ud55c \uacfc\ubaa9\ub9cc \ud558\uc138\uc694. \uc2dc\ud5d8\uc774\ub098 \ud3c9\uac00\uac00 \uc788\ub2e4\uba74 \uc0c8\ub85c\uc6b4 \uac83\uc744 \ubcf4\uc9c0 \ub9d0\uace0 \uc544\ub294 \uac83\uc744 \ubcf5\uc2b5\ud558\ub294 \ud3b8\uc774 \uc810\uc218\ub97c \uc9c0\ud0b5\ub2c8\ub2e4.',lucky:{color:'\uac80\uc740\uc0c9',food:'\ubbf8\uc5ed\uad6d',number:'4,9',person:'\uc5b4\uba38\ub2c8',direction:'\ubd81\ucabd',item:'\uc6b0\uc0b0'},tip:'\ub098\ub97c \uc9c0\ud0a4\ub294 \ucf54\ub514\n\uac80\uc740\uc0c9\uc774\ub098 \uc9d9\uc740 \ub0a8\uc0c9\ucc98\ub7fc \uae4a\uc740 \uc0c9\uc774 \uc624\ub298\uc758 \ubc29\ud328\uac00 \ub429\ub2c8\ub2e4. \ub208\uc5d0 \ub744\uc9c0 \uc54a\ub294 \ucc28\ub9bc\uc774 \ubd88\ud544\uc694\ud55c \uc9c0\uc801\uc744 \ud53c\ud558\uac8c \ud558\uace0, \ub2e8\uc815\ud55c \uc7ac\ud0b7\uc740 \ucc45\uc784\uc744 \uac10\ub2f9\ud560 \uc0ac\ub78c\uc73c\ub85c \ubcf4\uc774\uac8c \ud569\ub2c8\ub2e4. \uc6b0\uc0b0\uc744 \ucc59\uae30\uc138\uc694. \ube44 \uc18c\uc2dd\uc774 \uc5c6\uc5b4\ub3c4 \uc624\ub298\uc740 \ub300\ube44\ud558\ub294 \uc0ac\ub78c\uc774 \uc774\uae41\ub2c8\ub2e4. \uc18d\uc637\uc774\ub098 \uc591\ub9d0\uc744 \uc0c8\uac83\uc73c\ub85c \ubc14\uafb8\uba74 \uc561\uc744 \uac08\uc544\uc785\ub294 \ud6a8\uacfc\uac00 \uc788\uc2b5\ub2c8\ub2e4.'}}},446,[]);
